import { cookies, headers } from 'next/headers';

export default async function Home() {
  const cookieStore = await cookies();
  const headersList = await headers();

  const theme = cookieStore.get('theme')?.value || 'light';
  const acceptLanguage = headersList.get('accept-language') || 'Not specified';

  const preferredLanguage = acceptLanguage.split(',')[0].trim();

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>User Preferences</h1>

      <div style={{ marginTop: '2rem' }}>
        <h2>Theme Preference</h2>
        <p style={{
          padding: '1rem',
          backgroundColor: theme === 'dark' ? '#333' : '#f5f5f5',
          color: theme === 'dark' ? '#fff' : '#000',
          borderRadius: '8px'
        }}>
          Current theme: <strong>{theme}</strong>
        </p>
      </div>

      <div style={{ marginTop: '2rem' }}>
        <h2>Language Preference</h2>
        <p style={{
          padding: '1rem',
          backgroundColor: '#f5f5f5',
          borderRadius: '8px'
        }}>
          Preferred language: <strong>{preferredLanguage}</strong>
        </p>
        <details style={{ marginTop: '1rem' }}>
          <summary style={{ cursor: 'pointer' }}>Full Accept-Language header</summary>
          <pre style={{
            padding: '1rem',
            backgroundColor: '#f5f5f5',
            borderRadius: '8px',
            overflow: 'auto'
          }}>
            {acceptLanguage}
          </pre>
        </details>
      </div>
    </main>
  );
}

